enum class DungeonDirection(val dx: Int, val dy: Int) { NORTH(0,-1), EAST(1,0), SOUTH(0,1), WEST(-1,0); fun opposite() = when(this){ NORTH->SOUTH; EAST->WEST; SOUTH->NORTH; WEST->EAST } }
enum class DungeonRoomType { STANDARD, HALLWAY, OPEN, PILLAR, STAIRS_DOWN, STAIRS_UP, BOSS }
enum class SharedWallKind { SOLID, DOORWAY, OPEN }
data class DungeonCoord(val x:Int,val y:Int){ val id:String get()="$x,$y" }
data class DungeonDoorway(val wall:DungeonDirection,val offset:Int)
data class DungeonPillar(val x:Int,val y:Int,val variant:Int)
data class DungeonInteriorWall(val x:Int,val y:Int,val variant:Int)
data class DungeonStairs(val type:String,val variant:Int,val x:Int=4,val y:Int=4)
data class SharedDungeonWall(val key:String,val kind:SharedWallKind,val doorwayOffset:Int?,val wallVariants:List<Int>)
data class DungeonRoomData(val x:Int,val y:Int,var type:DungeonRoomType,val connections:MutableSet<DungeonDirection> = mutableSetOf(),val doorways:MutableList<DungeonDoorway> = mutableListOf(),val pillars:MutableList<DungeonPillar> = mutableListOf(),val interiorWalls:MutableList<DungeonInteriorWall> = mutableListOf(),var stairs:DungeonStairs?=null,var mergedGroup:String?=null,var floorTileVariants:List<Int> = emptyList()){ val coord:DungeonCoord get()=DungeonCoord(x,y) }
data class DungeonFloorData(val schemaVersion:Int=1,val tier:Int,val floor:Int,val theme:String,val seed:Long,val generated:Boolean,val startRoom:DungeonCoord,val stairsUpRoom:DungeonCoord,val bossRoom:DungeonCoord?,val bossRequired:Boolean,val rooms:List<DungeonRoomData>,val sharedWalls:Map<String,SharedDungeonWall>){ fun roomAt(x:Int,y:Int)=rooms[y*10+x]; fun wallFor(room:DungeonRoomData,d:DungeonDirection)=sharedWalls[DungeonGenerator.wallKey(room.x,room.y,d)]?:error("Missing wall") }
data class DungeonFloorState(val floor:Int,var currentRoom:DungeonCoord,val discoveredRooms:MutableSet<String> = mutableSetOf(),val openedChests:MutableSet<String> = mutableSetOf(),val defeatedEnemies:MutableSet<String> = mutableSetOf(),val collectedLoot:MutableSet<String> = mutableSetOf(),val unlockedDoors:MutableSet<String> = mutableSetOf(),val triggeredTraps:MutableSet<String> = mutableSetOf(),var bossDefeated:Boolean=false)

object DungeonFloorRepository {
    private fun floorDir(c:Context)=File(c.filesDir,"dungeon_floors").apply{mkdirs()}; private fun stateDir(c:Context)=File(c.filesDir,"dungeon_states").apply{mkdirs()}
    private fun floorFile(c:Context,f:Int)=File(floorDir(c),"floor_${f.toString().padStart(3,'0')}.json"); private fun stateFile(c:Context,f:Int)=File(stateDir(c),"floor_${f.toString().padStart(3,'0')}_state.json")
    fun loadOrGenerate(c:Context,floorNumber:Int):DungeonFloorData{ val file=floorFile(c,floorNumber); if(file.exists()) return runCatching{floorFromJson(JSONObject(file.readText()))}.getOrElse{throw IllegalStateException("Saved floor unreadable; refusing regeneration",it)}; val initial=SecureRandom().nextLong(); repeat(24){a-> val seed=initial+a*104729L; val g=DungeonGenerator.generate(floorNumber,seed); if(DungeonGenerator.validate(g).isEmpty()){atomicWrite(file,floorToJson(g).toString()); return g}}; error("Could not generate valid floor") }
    fun loadState(c:Context,f:DungeonFloorData):DungeonFloorState{ val file=stateFile(c,f.floor); if(!file.exists()) return DungeonFloorState(f.floor,f.startRoom,mutableSetOf(f.startRoom.id)).also{saveState(c,it)}; return runCatching{stateFromJson(JSONObject(file.readText()))}.getOrElse{DungeonFloorState(f.floor,f.startRoom,mutableSetOf(f.startRoom.id)).also{saveState(c,it)}} }
    fun saveState(c:Context,s:DungeonFloorState)=atomicWrite(stateFile(c,s.floor),stateToJson(s).toString())
    private fun atomicWrite(file:File,text:String){file.parentFile?.mkdirs(); val t=File(file.parentFile,file.name+".tmp"); t.writeText(text); if(file.exists()) file.delete(); check(t.renameTo(file))}
    private fun ia(v:List<Int>)=JSONArray().also{a->v.forEach(a::put)}; private fun sa(v:Set<String>)=JSONArray().also{a->v.sorted().forEach(a::put)}; private fun cj(c:DungeonCoord)=JSONObject().apply{put("x",c.x);put("y",c.y)}
    private fun floorToJson(f:DungeonFloorData)=JSONObject().apply{put("schemaVersion",f.schemaVersion);put("tier",f.tier);put("floor",f.floor);put("theme",f.theme);put("seed",f.seed);put("generated",f.generated);put("startRoom",cj(f.startRoom));put("stairsUpRoom",cj(f.stairsUpRoom));if(f.bossRoom==null)put("bossRoom",JSONObject.NULL)else put("bossRoom",cj(f.bossRoom));put("bossRequired",f.bossRequired);put("sharedWalls",JSONArray().also{a->f.sharedWalls.values.sortedBy{it.key}.forEach{w->a.put(JSONObject().apply{put("key",w.key);put("kind",w.kind.name);if(w.doorwayOffset==null)put("doorwayOffset",JSONObject.NULL)else put("doorwayOffset",w.doorwayOffset);put("wallVariants",ia(w.wallVariants))})}});put("rooms",JSONArray().also{a->f.rooms.forEach{r->a.put(JSONObject().apply{put("x",r.x);put("y",r.y);put("type",r.type.name);if(r.mergedGroup==null)put("mergedGroup",JSONObject.NULL)else put("mergedGroup",r.mergedGroup);put("connections",JSONArray().also{x->r.connections.sortedBy{it.ordinal}.forEach{x.put(it.name)}});put("doorways",JSONArray().also{x->r.doorways.forEach{d->x.put(JSONObject().apply{put("wall",d.wall.name);put("offset",d.offset)})}});put("pillars",JSONArray().also{x->r.pillars.forEach{p->x.put(JSONObject().apply{put("x",p.x);put("y",p.y);put("variant",p.variant)})}});put("interiorWalls",JSONArray().also{x->r.interiorWalls.forEach{w->x.put(JSONObject().apply{put("x",w.x);put("y",w.y);put("variant",w.variant)})}});put("floorTileVariants",ia(r.floorTileVariants));if(r.stairs==null)put("stairs",JSONObject.NULL)else put("stairs",JSONObject().apply{put("type",r.stairs!!.type);put("variant",r.stairs!!.variant);put("x",r.stairs!!.x);put("y",r.stairs!!.y)})})}})}
    private fun floorFromJson(o:JSONObject):DungeonFloorData{val walls=mutableMapOf<String,SharedDungeonWall>();val wa=o.getJSONArray("sharedWalls");for(i in 0 until wa.length()){val w=wa.getJSONObject(i);val v=w.getJSONArray("wallVariants");val d=SharedDungeonWall(w.getString("key"),SharedWallKind.valueOf(w.getString("kind")),if(w.isNull("doorwayOffset"))null else w.getInt("doorwayOffset"),List(v.length()){v.getInt(it)});walls[d.key]=d};val rooms=mutableListOf<DungeonRoomData>();val ra=o.getJSONArray("rooms");for(i in 0 until ra.length()){val r=ra.getJSONObject(i);val room=DungeonRoomData(r.getInt("x"),r.getInt("y"),DungeonRoomType.valueOf(r.getString("type")));if(!r.isNull("mergedGroup"))room.mergedGroup=r.getString("mergedGroup");val ca=r.getJSONArray("connections");for(j in 0 until ca.length())room.connections+=DungeonDirection.valueOf(ca.getString(j));val da=r.getJSONArray("doorways");for(j in 0 until da.length()){val d=da.getJSONObject(j);room.doorways+=DungeonDoorway(DungeonDirection.valueOf(d.getString("wall")),d.getInt("offset"))};val pa=r.getJSONArray("pillars");for(j in 0 until pa.length()){val p=pa.getJSONObject(j);room.pillars+=DungeonPillar(p.getInt("x"),p.getInt("y"),p.getInt("variant"))};val iw=r.getJSONArray("interiorWalls");for(j in 0 until iw.length()){val w=iw.getJSONObject(j);room.interiorWalls+=DungeonInteriorWall(w.getInt("x"),w.getInt("y"),w.getInt("variant"))};val fa=r.getJSONArray("floorTileVariants");room.floorTileVariants=List(fa.length()){fa.getInt(it)};if(!r.isNull("stairs")){val s=r.getJSONObject("stairs");room.stairs=DungeonStairs(s.getString("type"),s.getInt("variant"),s.getInt("x"),s.getInt("y"))};rooms+=room};return DungeonFloorData(o.optInt("schemaVersion",1),o.getInt("tier"),o.getInt("floor"),o.getString("theme"),o.getLong("seed"),o.getBoolean("generated"),cf(o.getJSONObject("startRoom")),cf(o.getJSONObject("stairsUpRoom")),if(o.isNull("bossRoom"))null else cf(o.getJSONObject("bossRoom")),o.getBoolean("bossRequired"),rooms,walls)}
    private fun stateToJson(s:DungeonFloorState)=JSONObject().apply{put("floor",s.floor);put("currentRoom",cj(s.currentRoom));put("discoveredRooms",sa(s.discoveredRooms));put("openedChests",sa(s.openedChests));put("defeatedEnemies",sa(s.defeatedEnemies));put("collectedLoot",sa(s.collectedLoot));put("unlockedDoors",sa(s.unlockedDoors));put("triggeredTraps",sa(s.triggeredTraps));put("bossDefeated",s.bossDefeated)}
    private fun stateFromJson(o:JSONObject)=DungeonFloorState(o.getInt("floor"),cf(o.getJSONObject("currentRoom")),ss(o.optJSONArray("discoveredRooms")),ss(o.optJSONArray("openedChests")),ss(o.optJSONArray("defeatedEnemies")),ss(o.optJSONArray("collectedLoot")),ss(o.optJSONArray("unlockedDoors")),ss(o.optJSONArray("triggeredTraps")),o.optBoolean("bossDefeated",false))
    private fun ss(a:JSONArray?)=mutableSetOf<String>().apply{if(a!=null)for(i in 0 until a.length())add(a.getString(i))}; private fun cf(o:JSONObject)=DungeonCoord(o.getInt("x"),o.getInt("y"))
}

object DungeonGenerator {
    private const val G=10; private const val R=10
    fun wallKey(x:Int,y:Int,d:DungeonDirection)=when(d){DungeonDirection.NORTH->if(y==0)"N:$x" else "H:$x:${y-1}";DungeonDirection.SOUTH->if(y==9)"S:$x" else "H:$x:$y";DungeonDirection.WEST->if(x==0)"W:$y" else "V:${x-1}:$y";DungeonDirection.EAST->if(x==9)"E:$y" else "V:$x:$y"}
    fun generate(floorNumber:Int,seed:Long):DungeonFloorData{val r=Random((seed xor(seed ushr 32)).toInt());val tier=(floorNumber-1)/10+1;val boss=floorNumber%10==0;val rooms=List(100){i->DungeonRoomData(i%10,i/10,DungeonRoomType.STANDARD)}.toMutableList();val start=edgeStart(r);var exit=distant(start,r);val links=Array(100){mutableSetOf<Int>()};maze(start.y*10+start.x,links,r);loops(links,r);var bossRep:DungeonCoord?=null;if(boss){val a=bossAnchor(start,r);val bc=listOf(DungeonCoord(a.x,a.y),DungeonCoord(a.x+1,a.y),DungeonCoord(a.x,a.y+1),DungeonCoord(a.x+1,a.y+1));val group="boss-$floorNumber";bc.forEach{rooms[idx(it.x,it.y)].mergedGroup=group};for(x in bc)for(y in bc)if(abs(x.x-y.x)+abs(x.y-y.y)==1)connect(links,idx(x.x,x.y),idx(y.x,y.y));exit=bc.maxBy{abs(it.x-start.x)+abs(it.y-start.y)};bossRep=exit}else{val far=coords().filter{abs(it.x-start.x)+abs(it.y-start.y)>=11};if(far.isNotEmpty())exit=far.random(r)};openGroups(rooms,links,start,exit,r);types(rooms,links,start,exit,r);val walls=walls(rooms,links,r);connections(rooms,walls);visuals(rooms,r);features(rooms,start,exit,r);hallways(rooms,walls,r);return DungeonFloorData(tier=tier,floor=floorNumber,theme=if(tier==1)"greystone" else "greystone-placeholder",seed=seed,generated=true,startRoom=start,stairsUpRoom=exit,bossRoom=bossRep,bossRequired=boss,rooms=rooms,sharedWalls=walls)}
    private fun edgeStart(r:Random)=when(r.nextInt(4)){0->DungeonCoord(r.nextInt(1,9),0);1->DungeonCoord(9,r.nextInt(1,9));2->DungeonCoord(r.nextInt(1,9),9);else->DungeonCoord(0,r.nextInt(1,9))}
    private fun distant(s:DungeonCoord,r:Random)=(coords().filter{abs(it.x-s.x)+abs(it.y-s.y)>=12}.ifEmpty{coords()}).random(r);private fun bossAnchor(s:DungeonCoord,r:Random)=buildList{for(y in 0..8)for(x in 0..8)if(abs(x+1-s.x)+abs(y+1-s.y)>=10)add(DungeonCoord(x,y))}.random(r)
    private fun coords()=List(100){DungeonCoord(it%10,it/10)};private fun idx(x:Int,y:Int)=y*10+x;private fun co(i:Int)=DungeonCoord(i%10,i/10);private fun neigh(i:Int)=buildList{val c=co(i);for(d in DungeonDirection.values()){val x=c.x+d.dx;val y=c.y+d.dy;if(x in 0..9&&y in 0..9)add(idx(x,y))}}
    private fun connect(l:Array<MutableSet<Int>>,a:Int,b:Int){l[a]+=b;l[b]+=a};private fun maze(s:Int,l:Array<MutableSet<Int>>,r:Random){val v=BooleanArray(100);val q=ArrayDeque<Int>();v[s]=true;q.add(s);while(q.isNotEmpty()){val c=q.peekLast();val u=neigh(c).filter{!v[it]};if(u.isEmpty())q.removeLast()else{val n=u.random(r);connect(l,c,n);v[n]=true;q.addLast(n)}}};private fun loops(l:Array<MutableSet<Int>>,r:Random){buildList<Pair<Int,Int>>{for(i in l.indices)for(n in neigh(i))if(i<n&&n !in l[i])add(i to n)}.shuffled(r).take(14+r.nextInt(8)).forEach{connect(l,it.first,it.second)}}
    private fun openGroups(rooms:MutableList<DungeonRoomData>,l:Array<MutableSet<Int>>,s:DungeonCoord,e:DungeonCoord,r:Random){var made=0;var tries=0;while(made<4&&tries++<80){val a=coords().random(r);val d=DungeonDirection.values().random(r);val b=DungeonCoord(a.x+d.dx,a.y+d.dy);if(b.x !in 0..9||b.y !in 0..9||a==s||a==e||b==s||b==e)continue;val ra=rooms[idx(a.x,a.y)];val rb=rooms[idx(b.x,b.y)];if(ra.mergedGroup!=null||rb.mergedGroup!=null)continue;val g="open-$made";ra.mergedGroup=g;rb.mergedGroup=g;connect(l,idx(a.x,a.y),idx(b.x,b.y));made++}}
    private fun dir(a:DungeonCoord,b:DungeonCoord)=when{b.x==a.x&&b.y==a.y-1->DungeonDirection.NORTH;b.x==a.x+1&&b.y==a.y->DungeonDirection.EAST;b.x==a.x&&b.y==a.y+1->DungeonDirection.SOUTH;else->DungeonDirection.WEST}
    private fun types(rooms:MutableList<DungeonRoomData>,l:Array<MutableSet<Int>>,s:DungeonCoord,e:DungeonCoord,r:Random){rooms.forEachIndexed{i,room->val c=co(i);room.type=when{c==s->DungeonRoomType.STAIRS_DOWN;room.mergedGroup?.startsWith("boss-")==true->DungeonRoomType.BOSS;c==e->DungeonRoomType.STAIRS_UP;room.mergedGroup!=null->DungeonRoomType.OPEN;else->{val ds=l[i].map{dir(c,co(it))};val straight=ds.size==2&&ds[0].opposite()==ds[1];when{straight&&r.nextFloat()<.72f->DungeonRoomType.HALLWAY;ds.size in 2..3&&r.nextFloat()<.22f->DungeonRoomType.HALLWAY;r.nextFloat()<.10f->DungeonRoomType.PILLAR;r.nextFloat()<.12f->DungeonRoomType.OPEN;else->DungeonRoomType.STANDARD}}}}}
    private fun walls(rooms:List<DungeonRoomData>,l:Array<MutableSet<Int>>,r:Random):Map<String,SharedDungeonWall>{val o=mutableMapOf<String,SharedDungeonWall>();fun vv()=List(10){r.nextInt(1,11)};for(x in 0..9){o["N:$x"]=SharedDungeonWall("N:$x",SharedWallKind.SOLID,null,vv());o["S:$x"]=SharedDungeonWall("S:$x",SharedWallKind.SOLID,null,vv())};for(y in 0..9){o["W:$y"]=SharedDungeonWall("W:$y",SharedWallKind.SOLID,null,vv());o["E:$y"]=SharedDungeonWall("E:$y",SharedWallKind.SOLID,null,vv())};for(y in 0..9)for(x in 0..8){val a=idx(x,y);val b=idx(x+1,y);val k="V:$x:$y";val same=rooms[a].mergedGroup!=null&&rooms[a].mergedGroup==rooms[b].mergedGroup;val kind=if(same)SharedWallKind.OPEN else if(b in l[a])SharedWallKind.DOORWAY else SharedWallKind.SOLID;o[k]=SharedDungeonWall(k,kind,if(kind==SharedWallKind.DOORWAY)r.nextInt(2,8)else null,vv())};for(y in 0..8)for(x in 0..9){val a=idx(x,y);val b=idx(x,y+1);val k="H:$x:$y";val same=rooms[a].mergedGroup!=null&&rooms[a].mergedGroup==rooms[b].mergedGroup;val kind=if(same)SharedWallKind.OPEN else if(b in l[a])SharedWallKind.DOORWAY else SharedWallKind.SOLID;o[k]=SharedDungeonWall(k,kind,if(kind==SharedWallKind.DOORWAY)r.nextInt(2,8)else null,vv())};return o}
    private fun connections(rooms:MutableList<DungeonRoomData>,w:Map<String,SharedDungeonWall>){for(room in rooms){room.connections.clear();room.doorways.clear();for(d in DungeonDirection.values()){val x=w[wallKey(room.x,room.y,d)]?:continue;if(x.kind!=SharedWallKind.SOLID)room.connections+=d;if(x.kind==SharedWallKind.DOORWAY)room.doorways+=DungeonDoorway(d,x.doorwayOffset!!)}}}
    private fun visuals(rooms:MutableList<DungeonRoomData>,r:Random){for(room in rooms){val base=r.nextInt(1,11);room.floorTileVariants=List(100){i->val x=i%10;val y=i/10;val c=((x/3)+(y/3)+base-1)%10+1;when{r.nextFloat()<.68f->c;r.nextFloat()<.72f->base;else->r.nextInt(1,11)}}}}
    private fun features(rooms:MutableList<DungeonRoomData>,s:DungeonCoord,e:DungeonCoord,r:Random){rooms[idx(s.x,s.y)].stairs=DungeonStairs("down",r.nextInt(1,4));rooms[idx(e.x,e.y)].stairs=DungeonStairs("up",r.nextInt(1,4));for(room in rooms){when(room.type){DungeonRoomType.BOSS->{val gr=rooms.filter{it.mergedGroup==room.mergedGroup};val minX=gr.minOf{it.x};val minY=gr.minOf{it.y};room.pillars+=DungeonPillar(if(room.x==minX)2 else 7,if(room.y==minY)2 else 7,r.nextInt(1,5))};DungeonRoomType.PILLAR->{val lays=listOf(listOf(2 to 2,7 to 2,2 to 7,7 to 7),listOf(3 to 2,6 to 2,3 to 7,6 to 7),listOf(2 to 4,7 to 4),listOf(4 to 2,4 to 7));lays.random(r).forEach{(x,y)->room.pillars+=DungeonPillar(x,y,r.nextInt(1,5))}};DungeonRoomType.OPEN->if(r.nextFloat()<.35f)listOf(3 to 3,6 to 6).forEach{(x,y)->room.pillars+=DungeonPillar(x,y,r.nextInt(1,5))};else->Unit}}}
    private fun hallways(rooms:MutableList<DungeonRoomData>,w:Map<String,SharedDungeonWall>,r:Random){for(room in rooms.filter{it.type==DungeonRoomType.HALLWAY}){val open=mutableSetOf<Pair<Int,Int>>();for(y in 3..6)for(x in 3..6)open+=x to y;for(d in room.connections){val wall=w[wallKey(room.x,room.y,d)]!!;val off=wall.doorwayOffset?:4;when(d){DungeonDirection.NORTH->for(y in 1..4)for(x in off-1..off+1)open+=x to y;DungeonDirection.SOUTH->for(y in 5..8)for(x in off-1..off+1)open+=x to y;DungeonDirection.WEST->for(x in 1..4)for(y in off-1..off+1)open+=x to y;DungeonDirection.EAST->for(x in 5..8)for(y in off-1..off+1)open+=x to y}};for(y in 1..8)for(x in 1..8)if((x to y)!in open)room.interiorWalls+=DungeonInteriorWall(x,y,r.nextInt(1,11))}}
    fun validate(f:DungeonFloorData):List<String>{val e=mutableListOf<String>();if(f.rooms.size!=100)e+="room count";if(f.rooms.count{it.stairs?.type=="down"}!=1)e+="stairs down count";if(f.rooms.count{it.stairs?.type=="up"}!=1)e+="stairs up count";for(x in 0..9){if(f.sharedWalls["N:$x"]?.kind!=SharedWallKind.SOLID)e+="north edge";if(f.sharedWalls["S:$x"]?.kind!=SharedWallKind.SOLID)e+="south edge"};for(y in 0..9){if(f.sharedWalls["W:$y"]?.kind!=SharedWallKind.SOLID)e+="west edge";if(f.sharedWalls["E:$y"]?.kind!=SharedWallKind.SOLID)e+="east edge"};val seen=mutableSetOf(f.startRoom.id);val q=ArrayDeque<DungeonCoord>();q.add(f.startRoom);while(q.isNotEmpty()){val c=q.removeFirst();val room=f.roomAt(c.x,c.y);for(d in room.connections){val n=DungeonCoord(c.x+d.dx,c.y+d.dy);if(n.x !in 0..9||n.y !in 0..9){e+="outside connection";continue};if(d.opposite() !in f.roomAt(n.x,n.y).connections)e+="mismatch";if(seen.add(n.id))q.add(n)}};if(f.stairsUpRoom.id !in seen)e+="exit unreachable";if(seen.size!=100)e+="disconnected";if(f.bossRequired&&f.bossRoom?.id !in seen)e+="boss unreachable";for(room in f.rooms)e+=localValidate(f,room);return e.distinct()}
    private fun localValidate(f:DungeonFloorData,room:DungeonRoomData):List<String>{val e=mutableListOf<String>();val b=mutableSetOf<Pair<Int,Int>>();room.interiorWalls.forEach{b+=it.x to it.y};room.pillars.forEach{b+=it.x to it.y};for(i in 0..9){b+=i to 0;b+=i to 9;b+=0 to i;b+=9 to i};val entries=mutableListOf<Pair<Int,Int>>();for(d in room.connections){val w=f.wallFor(room,d);val off=w.doorwayOffset?:4;val pts=if(w.kind==SharedWallKind.OPEN)(1..8).map{i->when(d){DungeonDirection.NORTH->i to 0;DungeonDirection.SOUTH->i to 9;DungeonDirection.WEST->0 to i;DungeonDirection.EAST->9 to i}}else listOf(when(d){DungeonDirection.NORTH->off to 0;DungeonDirection.SOUTH->off to 9;DungeonDirection.WEST->0 to off;DungeonDirection.EAST->9 to off});pts.forEach{b.remove(it)};entries+=pts[pts.size/2]};room.stairs?.let{entries+=it.x to it.y};if(entries.isEmpty())return listOf("no route ${room.coord.id}");val seen=mutableSetOf<Pair<Int,Int>>();val q=ArrayDeque<Pair<Int,Int>>();if(entries.first() !in b){seen+=entries.first();q.add(entries.first())};val st=listOf(1 to 0,-1 to 0,0 to 1,0 to -1);while(q.isNotEmpty()){val c=q.removeFirst();for((dx,dy) in st){val n=(c.first+dx) to (c.second+dy);if(n.first in 0..9&&n.second in 0..9&&n !in b&&seen.add(n))q.add(n)}};if(entries.any{it !in seen})e+="blocked route ${room.coord.id}";return e}
}

private val DDark=Color(0xFF110E0C);private val DBrown=Color(0xFF342820);private val DGold=Color(0xFFFFC54B);private val DCream=Color(0xFFF4E2C0)
@Composable fun PersistentDungeonScreen(frogColor:FrogColor,level:Int,xp:Int,highestDungeonFloor:Int,helperCount:Int,onRecoverLoot:(Int)->Unit,onAdvanceFloor:()->Unit,onCharacterDeath:()->Unit){val c=androidx.compose.ui.platform.LocalContext.current;val floor=remember(highestDungeonFloor){DungeonFloorRepository.loadOrGenerate(c,highestDungeonFloor)};var state by remember(highestDungeonFloor){mutableStateOf(DungeonFloorRepository.loadState(c,floor))};var rx by rememberSaveable(highestDungeonFloor){mutableStateOf(state.currentRoom.x)};var ry by rememberSaveable(highestDungeonFloor){mutableStateOf(state.currentRoom.y)};val room=floor.roomAt(rx,ry);fun move(d:DungeonDirection){if(d !in room.connections)return;val nx=rx+d.dx;val ny=ry+d.dy;if(nx !in 0..9||ny !in 0..9)return;rx=nx;ry=ny;state.currentRoom=DungeonCoord(nx,ny);state.discoveredRooms+=state.currentRoom.id;DungeonFloorRepository.saveState(c,state);state=state.copy(discoveredRooms=state.discoveredRooms.toMutableSet())};Column(Modifier.fillMaxSize().background(DDark).padding(bottom=82.dp).verticalScroll(rememberScrollState()),horizontalAlignment=Alignment.CenterHorizontally){Text("TOWER DUNGEON",color=DGold,fontWeight=FontWeight.Black,fontSize=24.sp,modifier=Modifier.padding(top=10.dp));Text("Floor ${floor.floor} • Tier ${floor.tier} • Room ($rx,$ry) • ${room.type.name.replace('_',' ')}",color=DCream,fontSize=12.sp);Text("Seed ${floor.seed} • ${state.discoveredRooms.size}/100 rooms discovered",color=Color.Gray,fontSize=9.sp);Button({move(DungeonDirection.NORTH)},enabled=DungeonDirection.NORTH in room.connections,modifier=Modifier.padding(top=6.dp)){Text("▲ North")};Row(Modifier.fillMaxWidth().padding(horizontal=5.dp),verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.Center){Button({move(DungeonDirection.WEST)},enabled=DungeonDirection.WEST in room.connections){Text("◀")};DungeonRoomCanvas(floor,room,Modifier.weight(1f).aspectRatio(1f));Button({move(DungeonDirection.EAST)},enabled=DungeonDirection.EAST in room.connections){Text("▶")}};Button({move(DungeonDirection.SOUTH)},enabled=DungeonDirection.SOUTH in room.connections){Text("▼ South")};Card(Modifier.fillMaxWidth().padding(10.dp),colors=CardDefaults.cardColors(containerColor=DBrown)){Column(Modifier.padding(10.dp)){Text("Room ${room.coord.id}",color=DGold,fontWeight=FontWeight.Black);Text("Connections: ${room.connections.joinToString{it.name.lowercase()}}",color=DCream,fontSize=10.sp);room.stairs?.let{Text("Stairs ${it.type.uppercase()} • visual ${it.variant}",color=Color(0xFFBFD8FF),fontSize=10.sp)};if(room.type==DungeonRoomType.BOSS)Text("BOSS ARENA • exit locked until boss defeat",color=Color(0xFFFF8A70),fontWeight=FontWeight.Bold,fontSize=10.sp)}};if(room.stairs?.type=="up"){val locked=floor.bossRequired&&!state.bossDefeated;Button(onAdvanceFloor,enabled=!locked){Text(if(locked)"Stairs Up Locked — Defeat Boss" else "Use Stairs Up")}};if(room.type==DungeonRoomType.BOSS&&!state.bossDefeated)TextButton({state.bossDefeated=true;DungeonFloorRepository.saveState(c,state);state=state.copy(bossDefeated=true)}){Text("Development: Mark Boss Defeated",color=Color(0xFFE8A38D))};Card(Modifier.fillMaxWidth().padding(10.dp),colors=CardDefaults.cardColors(containerColor=Color(0xFF261E18))){Column(Modifier.padding(9.dp)){Text("PERSISTENT FLOOR",color=DGold,fontWeight=FontWeight.Black,fontSize=11.sp);Text("Generated once, validated, and saved. Returning restores the exact maze, shared walls, doors, pillars, stairs, visual variants and seed.",color=DCream,fontSize=9.sp);Text("Hero L$level • XP $xp/${xpRequiredForNextLevel(xp)} • $helperCount helpers • ${frogColor.displayName} immunity",color=Color(0xFFC8B8A1),fontSize=9.sp);Button({onRecoverLoot(floor.tier)}){Text("Test Recover Tier ${floor.tier} Loot (+${floor.tier} XP)")}}};TextButton(onCharacterDeath){Text("Development: Character Death",color=Color(0xFFE58C82),fontSize=10.sp)}}}
@Composable private fun DungeonRoomCanvas(f:DungeonFloorData,r:DungeonRoomData,m:Modifier=Modifier){val c=androidx.compose.ui.platform.LocalContext.current;val fa=remember{ImageBitmap.imageResource(c.resources,R.drawable.greystone_floors)};val wa=remember{ImageBitmap.imageResource(c.resources,R.drawable.greystone_walls)};val da=remember{ImageBitmap.imageResource(c.resources,R.drawable.greystone_stairs_down)};val ua=remember{ImageBitmap.imageResource(c.resources,R.drawable.greystone_stairs_up)};val pa=remember{ImageBitmap.imageResource(c.resources,R.drawable.greystone_pillars)};Canvas(m.background(Color.Black,RoundedCornerShape(3.dp))){val cell=size.minDimension/10f;for(y in 0..9)for(x in 0..9)tile(fa,r.floorTileVariants.getOrElse(y*10+x){1},5,x*cell,y*cell,cell,cell);fun edge(d:DungeonDirection){val w=f.wallFor(r,d);for(i in 0..9){val draw=when(w.kind){SharedWallKind.SOLID->true;SharedWallKind.DOORWAY->i!=w.doorwayOffset;SharedWallKind.OPEN->i==0||i==9};if(!draw)continue;val x=when(d){DungeonDirection.WEST->0;DungeonDirection.EAST->9;else->i};val y=when(d){DungeonDirection.NORTH->0;DungeonDirection.SOUTH->9;else->i};tile(wa,w.wallVariants.getOrElse(i){1},5,x*cell,y*cell,cell,cell)}};DungeonDirection.values().forEach{edge(it)};r.interiorWalls.forEach{tile(wa,it.variant,5,it.x*cell,it.y*cell,cell,cell)};r.pillars.forEach{tile(pa,it.variant,4,it.x*cell,it.y*cell,cell,cell)};r.stairs?.let{tile(if(it.type=="down")da else ua,it.variant,3,3.1f*cell,3.1f*cell,3.8f*cell,3.8f*cell)};for(i in 0..10){drawLine(Color.Black.copy(alpha=.22f),Offset(i*cell,0f),Offset(i*cell,10*cell),1f);drawLine(Color.Black.copy(alpha=.22f),Offset(0f,i*cell),Offset(10*cell,i*cell),1f)};drawCircle(Color(0xFF65D34E),cell*.26f,Offset(5f*cell,5f*cell));drawCircle(Color(0xFFFFD45A),cell*.30f,Offset(5f*cell,5f*cell),style=androidx.compose.ui.graphics.drawscope.Stroke(2.5f))}}
private fun DrawScope.tile(a:ImageBitmap,v:Int,cols:Int,l:Float,t:Float,w:Float,h:Float){val n=(v-1).coerceAtLeast(0);val s=160;drawImage(a,IntOffset((n%cols)*s,(n/cols)*s),IntSize(s,s),IntOffset(l.roundToInt(),t.roundToInt()),IntSize(w.roundToInt().coerceAtLeast(1),h.roundToInt().coerceAtLeast(1)))}
